alter table public.frankiflow_site_settings
  add column if not exists about_eyebrow text not null default 'Über uns',
  add column if not exists about_title text not null default 'Persönlich aufgebaut. Digital gedacht. Mit Qualitätsanspruch.',
  add column if not exists about_body_1 text not null default 'FrankiFlow ist aus dem Wunsch entstanden, Service in Frankfurt einfacher, transparenter und persönlicher zu machen. Ich kam 2019 nach Deutschland, habe Mobility & Logistics studiert und anschließend im Fleet Management eines Reise- und Transportunternehmens gearbeitet. Qualitätskontrollen und strukturierte Abläufe gehörten dort zu meinem Alltag – genau diesen Anspruch bringe ich heute in FrankiFlow ein.',
  add column if not exists about_body_2 text not null default 'Der digitale Teil gehört von Anfang an dazu: Alex, Software Engineer und Masterstudent in Deutschland, hat unseren eigenen Preisrechner entwickelt und arbeitet heute mit mir am weiteren Aufbau. Unser Ziel ist kein schnelles Wachstum um jeden Preis, sondern ein verlässliches Team, klare Prozesse und eine Schritt-für-Schritt-Erweiterung von Frankfurt aus.',
  add column if not exists about_eyebrow_en text not null default 'About Us',
  add column if not exists about_title_en text not null default 'Built Personally. Designed Digitally. Focused on Quality.',
  add column if not exists about_body_1_en text not null default 'FrankiFlow grew from a simple idea: make service in Frankfurt easier, more transparent and more personal. I came to Germany in 2019, studied Mobility & Logistics and later worked in Fleet Management for a travel and transportation company. Quality checks and structured processes were part of my daily work, and I bring that same standard to FrankiFlow today.',
  add column if not exists about_body_2_en text not null default 'The digital side has been part of FrankiFlow from the beginning. Alex, a Software Engineer and Master’s student in Germany, developed our own Price Calculator and now works with me on building the company further. Our goal is not growth at any cost, but a reliable team, clear processes and careful step-by-step expansion from Frankfurt.',
  add column if not exists faq_eyebrow text not null default 'Häufige Fragen',
  add column if not exists faq_title text not null default 'Gebäudereinigung in Frankfurt: kurz beantwortet.',
  add column if not exists faq_intro text not null default 'Die wichtigsten Punkte vor Ihrer ersten Anfrage.',
  add column if not exists faq_eyebrow_en text not null default 'Frequently Asked Questions',
  add column if not exists faq_title_en text not null default 'Cleaning in Frankfurt: Quick Answers.',
  add column if not exists faq_intro_en text not null default 'The Key Points Before Your First Enquiry.',
  add column if not exists faq_items jsonb not null default '[{"question_de":"Was kostet eine Reinigung in Frankfurt?","answer_de":"Der Preis hängt von Leistung, Fläche, Häufigkeit, Laufzeit und Zusatzleistungen ab. Für eine schnelle Orientierung können Sie unseren Preisrechner nutzen; ein verbindliches Angebot folgt nach Abstimmung des Leistungsumfangs.","question_en":"How Much Does Cleaning Cost in Frankfurt?","answer_en":"The Price depends on the Service, Area, Frequency, Contract Term and any Extras. Use our Price Calculator for a quick Estimate; a binding Quote follows after the Scope has been agreed."},{"question_de":"Welche Reinigungsleistungen bietet FrankiFlow an?","answer_de":"Unter anderem Büroreinigung, Wohnungsreinigung, Airbnb- und Ferienwohnungsreinigung, Treppenhausreinigung, Grund- und Endreinigung sowie Objektbetreuung.","question_en":"Which Cleaning Services Does FrankiFlow Offer?","answer_en":"Services include Office Cleaning, Home Cleaning, Airbnb and Holiday-Rental Cleaning, Stairwell Cleaning, Deep/End-of-Tenancy Cleaning and Property Care."},{"question_de":"Kann die Büroreinigung außerhalb der Arbeitszeiten stattfinden?","answer_de":"Ja. Einsatzzeiten werden individuell abgestimmt, damit die Reinigung möglichst gut zu Ihrem Betriebsablauf passt.","question_en":"Can Office Cleaning Take Place Outside Working Hours?","answer_en":"Yes. Cleaning Times are agreed individually to fit your Business Operations as well as possible."},{"question_de":"Können Reinigungsmittel und Equipment gestellt werden?","answer_de":"Ja. Je nach Auftrag können Material und Equipment durch FrankiFlow gestellt oder vorhandene Mittel vor Ort genutzt werden. Die Vereinbarung wird vor Beginn klar festgehalten.","question_en":"Can Cleaning Supplies and Equipment Be Provided?","answer_en":"Yes. Depending on the Job, FrankiFlow can provide Supplies and Equipment or use suitable Materials already on site. This is agreed clearly before Work begins."},{"question_de":"Wie erhalte ich ein konkretes Angebot?","answer_de":"Nutzen Sie den Preisrechner oder senden Sie eine Anfrage mit Objektart, Fläche, gewünschter Häufigkeit und Besonderheiten. Wir melden uns persönlich zur Abstimmung.","question_en":"How Do I Get a Specific Quote?","answer_en":"Use the Price Calculator or send an Enquiry with the Property Type, Area, preferred Frequency and any special Requirements. We will contact you personally to agree the Details."}]'::jsonb,
  add column if not exists section_visibility jsonb not null default '{"hero":true,"advantages":true,"services":true,"about":true,"why":true,"process":true,"gallery":true,"faq":true,"contact":true}'::jsonb;
